  INVALID_TOTAL_PLAYERS: '人數必須係 1–8 人。',
};

function explainBotError(payload) {
  if (!payload || typeof payload !== 'object') return '服務暫時忙碌，請稍後再試。';
  const code = payload.code;
  if (code && ERROR_ZH[code]) {
    let msg = ERROR_ZH[code];
    if (code === 'INSUFFICIENT_BALANCE' && payload.details) {
      msg += `（需要 ${payload.details.required}，餘額 ${payload.details.available}）`;
    }
    return msg;
  }
  return payload.message || '操作失敗，請稍後再試。';
}

async function botGet(path) {
  return requestJson.call(this, 'GET', `${BOT_BASE}${path}`, { 'X-Bot-Key': BOT_KEY });
}
async function botPost(path, body) {
  return requestJson.call(this, 'POST', `${BOT_BASE}${path}`, { 'X-Bot-Key': BOT_KEY }, body);
}

